"""Dataset preparation (MultiTQ, TimelineKGQA, generated MultiTQ-style sets) and the shared top-N candidate pool."""

# MultiTQ-format question sets generated by tear.data.qgen (scripts/17_generate_questions.py)
GENERATED = ("icews18", "icews0515_regen")


def is_multitq(ds: str) -> bool:
    """MultiTQ, its question variants (multitq_orig: original questions instead of TimeR4's rewrites) and the
    generated MultiTQ-style sets (icews18, icews0515_regen) share the MultiTQ fact table and question schema."""
    return ds.startswith("multitq") or ds in GENERATED
